import path from 'node:path'

const dataDir = path.resolve(process.env.BOOKSERVE_DATA_DIR || 'data')

export const config = {
  dataDir,
  libraryDir: path.resolve(
    process.env.BOOKSERVE_LIBRARY_DIR || path.join(dataDir, 'library'),
  ),
  databasePath: path.join(dataDir, 'bookserve.db'),
  secretPath: path.join(dataDir, 'secret'),
  // Committed migrations; the server runs from the repo root (or /app in the image).
  migrationsDir: path.resolve('drizzle'),
  publicUrl: process.env.BOOKSERVE_URL || undefined,
  googleBooksApiKey: process.env.GOOGLE_BOOKS_API_KEY || undefined,
}
import fs from 'node:fs'
import Database from 'better-sqlite3'
import { drizzle } from 'drizzle-orm/better-sqlite3'
import { migrate } from 'drizzle-orm/better-sqlite3/migrator'

import { config } from '#/lib/config'
import * as schema from './schema.ts'

// Create the data and library dirs, open the DB, and apply pending migrations.
function openDatabase() {
  fs.mkdirSync(config.dataDir, { recursive: true })
  fs.mkdirSync(config.libraryDir, { recursive: true })

  const sqlite = new Database(config.databasePath)
  sqlite.pragma('journal_mode = WAL')
  sqlite.pragma('foreign_keys = ON')

  const database = drizzle(sqlite, { schema })
  migrate(database, { migrationsFolder: config.migrationsDir })
  return database
}

// One connection per process: Nitro's startup plugin and the SSR bundle each include
// this module (and dev reloads re-evaluate it), so the instance lives on globalThis.
const globalForDb = globalThis as typeof globalThis & {
  bookserveDb?: ReturnType<typeof openDatabase>
}

export const db = (globalForDb.bookserveDb ??= openDatabase())
import { definePlugin } from 'nitro'

// Importing auth initializes everything at boot instead of on the first request:
// data/library dirs, the SQLite DB and its migrations (src/db), and the auth secret.
import '#/lib/auth'
import { scanLibrary } from '#/lib/scanner'

export default definePlugin(() => {
  // In the background: the server starts serving while the library is scanned.
  void scanLibrary()
})
import crypto from 'node:crypto'
import fs from 'node:fs'
import fsp from 'node:fs/promises'
import path from 'node:path'
import { Readable } from 'node:stream'
import { pipeline } from 'node:stream/promises'
import type { ReadableStream as WebReadableStream } from 'node:stream/web'
import { eq } from 'drizzle-orm'

import { db } from '#/db'
import { bookFiles, books } from '#/db/schema'
import { resolveInside, sortKey } from '#/lib/books'
import { config } from '#/lib/config'
import { readEpub } from '#/lib/epub'
import type { EpubCover } from '#/lib/epub'

export type ScanResult = {
  added: number
  updated: number
  moved: number
  missing: number
  failed: number
  error?: string
}

type DiskFile = { rel: string; abs: string; size: number; mtimeMs: number }
type FileOutcome = 'unchanged' | 'added' | 'updated' | 'moved' | 'failed'

// Scans and imports run one at a time. The state lives on globalThis because the
// Nitro startup plugin and the SSR bundle each get their own copy of this module.
const state = ((
  globalThis as typeof globalThis & {
    bookserveScanner?: {
      tail: Promise<unknown>
      scan: Promise<ScanResult> | null
    }
  }
).bookserveScanner ??= { tail: Promise.resolve(), scan: null })

function serialize<T>(task: () => Promise<T>) {
  const run = state.tail.then(task)
  state.tail = run.catch(() => {})
  return run
}

// Full library scan. A call while a scan is running joins that scan.
export function scanLibrary() {
  state.scan ??= serialize(fullScan).finally(() => {
    state.scan = null
  })
  return state.scan
}

async function fullScan(): Promise<ScanResult> {
  const result: ScanResult = {
    added: 0,
    updated: 0,
    moved: 0,
    missing: 0,
    failed: 0,
  }
  const started = Date.now()
  const root = config.libraryDir

  // If the library itself is gone (e.g. an unmounted NAS share), touch nothing.
  try {
    await fsp.readdir(root)
  } catch (err) {
    result.error = `Library directory is not readable: ${root}`
    console.error(`[scan] ${result.error}`, err)
    return result
  }

  const { files, complete } = await walk(root)
  const onDisk = new Set(files.map((f) => f.rel))
  const seenBookIds = new Set<string>()

  for (const file of files) {
    try {
      const outcome = await importDiskFile(file, (rel) => onDisk.has(rel))
      if (outcome.bookId) seenBookIds.add(outcome.bookId)
      if (outcome.result !== 'unchanged') result[outcome.result]++
    } catch (err) {
      result.failed++
      console.error(`[scan] Failed to import ${file.rel}:`, err)
    }
    // Let requests through between files.
    await new Promise((resolve) => setImmediate(resolve))
  }

  // Books whose files all vanished are flagged, never deleted. Skip this if part
  // of the tree could not be read, so an I/O error doesn't hide books.
  if (complete) {
    const rows = db
      .select({ id: books.id, missing: books.missing })
      .from(books)
      .all()
    db.transaction((tx) => {
      for (const row of rows) {
        const missing = !seenBookIds.has(row.id)
        if (missing === row.missing) continue
        tx.update(books).set({ missing }).where(eq(books.id, row.id)).run()
        if (missing) result.missing++
      }
    })
  }

  console.log(
    `[scan] Done in ${Date.now() - started}ms: ${files.length} files, ` +
      `${result.added} added, ${result.updated} updated, ${result.moved} moved, ` +
      `${result.missing} newly missing, ${result.failed} failed`,
  )
  return result
}

// Recursively lists .epub files. Hidden entries (e.g. macOS ._ files) are skipped.
async function walk(root: string) {
  const files: DiskFile[] = []
  let complete = true
  const visit = async (dir: string) => {
    let entries: fs.Dirent[]
    try {
      entries = await fsp.readdir(dir, { withFileTypes: true })
    } catch (err) {
      complete = false
      console.error(`[scan] Cannot read ${dir}:`, err)
      return
    }
    for (const entry of entries) {
      if (entry.name.startsWith('.')) continue
      const abs = path.join(dir, entry.name)
      if (entry.isDirectory()) {
        await visit(abs)
      } else if (entry.isFile() && /\.epub$/i.test(entry.name)) {
        try {
          const stat = await fsp.stat(abs)
          files.push({
            rel: path.relative(root, abs).split(path.sep).join('/'),
            abs,
            size: stat.size,
            mtimeMs: Math.trunc(stat.mtimeMs),
          })
        } catch (err) {
          complete = false
          console.error(`[scan] Cannot stat ${abs}:`, err)
        }
      }
    }
  }
  await visit(root)
  return { files, complete }
}

// Reconciles one file on disk with the DB. `onDisk` tells whether a stored path
// still exists, to recognize a known file (by hash) that was moved here.
async function importDiskFile(
  file: DiskFile,
  onDisk: (rel: string) => boolean,
): Promise<{ result: FileOutcome; bookId?: string }> {
  const existing = db
    .select()
    .from(bookFiles)
    .where(eq(bookFiles.path, file.rel))
    .get()
  if (
    existing &&
    existing.size === file.size &&
    existing.mtimeMs === file.mtimeMs
  ) {
    return { result: 'unchanged', bookId: existing.bookId }
  }

  const data = await fsp.readFile(file.abs)
  const hash = crypto.createHash('sha256').update(data).digest('hex')
  const stats = { size: file.size, mtimeMs: file.mtimeMs, hash }

  if (!existing) {
    const moved = db
      .select()
      .from(bookFiles)
      .where(eq(bookFiles.hash, hash))
      .all()
      .find((row) => !onDisk(row.path))
    if (moved) {
      db.transaction((tx) => {
        tx.update(bookFiles)
          .set({ path: file.rel, ...stats })
          .where(eq(bookFiles.id, moved.id))
          .run()
        tx.update(books)
          .set({ missing: false })
          .where(eq(books.id, moved.bookId))
          .run()
      })
      console.log(`[scan] Moved ${moved.path} -> ${file.rel}`)
      return { result: 'moved', bookId: moved.bookId }
    }
  }

  let parsed: ReturnType<typeof readEpub>
  try {
    parsed = readEpub(data)
  } catch (err) {
    console.warn(
      `[scan] Skipping unreadable EPUB ${file.rel}: ${err instanceof Error ? err.message : err}`,
    )
    return { result: 'failed', bookId: existing?.bookId }
  }
  const { metadata, cover } = parsed
  const title =
    metadata.title || path.basename(file.rel, path.extname(file.rel))
  const bookId = existing?.bookId ?? crypto.randomUUID()
  const coverPath = await writeCover(bookId, cover)
  const fields = {
    ...metadata,
    title,
    sortTitle: sortKey(title),
    coverPath,
    missing: false,
  }

  db.transaction((tx) => {
    if (existing) {
      tx.update(books).set(fields).where(eq(books.id, bookId)).run()
      tx.update(bookFiles).set(stats).where(eq(bookFiles.id, existing.id)).run()
    } else {
      tx.insert(books)
        .values({ id: bookId, ...fields })
        .run()
      tx.insert(bookFiles)
        .values({ bookId, path: file.rel, format: 'epub', ...stats })
        .run()
    }
  })
  console.log(`[scan] ${existing ? 'Updated' : 'Added'} ${file.rel}`)
  return { result: existing ? 'updated' : 'added', bookId }
}

// Writes the cover to <data>/covers/<bookId>.<ext>, replacing any previous one.
// Returns its path relative to the data dir.
async function writeCover(bookId: string, cover: EpubCover | null) {
  const dir = path.join(config.dataDir, 'covers')
  await fsp.mkdir(dir, { recursive: true })
  for (const name of await fsp.readdir(dir)) {
    if (name.startsWith(`${bookId}.`)) await fsp.rm(path.join(dir, name))
  }
  if (!cover) return null
  await fsp.writeFile(path.join(dir, `${bookId}.${cover.ext}`), cover.data)
  return `covers/${bookId}.${cover.ext}`
}

// Deletes a book's files from the library, its row (book_files cascade) and its
// scanned and matched covers. Runs in the scan queue so a scan can't re-add it.
export function deleteBook(bookId: string) {
  return serialize(async () => {
    const files = db
      .select({ path: bookFiles.path })
      .from(bookFiles)
      .where(eq(bookFiles.bookId, bookId))
      .all()
    // Files go first: if one can't be removed, the book stays in the library.
    for (const file of files) {
      const abs = resolveInside(config.libraryDir, file.path)
      if (abs) await fsp.rm(abs, { force: true })
    }
    const deleted = db.delete(books).where(eq(books.id, bookId)).run()
    if (!deleted.changes) throw new Error('Book not found')
    const dir = path.join(config.dataDir, 'covers')
    for (const name of await fsp.readdir(dir).catch(() => [])) {
      if (
        name.startsWith(`${bookId}.`) ||
        name.startsWith(`${bookId}-matched.`)
      ) {
        await fsp.rm(path.join(dir, name), { force: true })
      }
    }
    console.log(`[scan] Deleted ${files.map((f) => f.path).join(', ')}`)
  })
}

export class UploadError extends Error {}

// Streams an uploaded EPUB to a temp file in the data dir, reads its metadata,
// then places it at <library>/<Author>/<Title>/<name> (never overwriting) and
// imports it. This and deleteBook are the only places the app changes the library.
export async function uploadBook(
  fileName: string,
  body: WebReadableStream<Uint8Array>,
) {
  const tmpDir = path.join(config.dataDir, 'tmp')
  await fsp.mkdir(tmpDir, { recursive: true })
  const tmp = path.join(tmpDir, `${crypto.randomUUID()}.epub`)
  try {
    await pipeline(Readable.fromWeb(body), fs.createWriteStream(tmp))

    let metadata
    try {
      metadata = readEpub(await fsp.readFile(tmp)).metadata
    } catch {
      throw new UploadError(`${fileName} is not a valid EPUB`)
    }

    const base = path.basename(fileName, path.extname(fileName))
    const dir = path.join(
      config.libraryDir,
      safeSegment(metadata.authors[0] ?? '', 'Unknown Author'),
      safeSegment(metadata.title, safeSegment(base, 'Untitled')),
    )
    await fsp.mkdir(dir, { recursive: true })
    const dest = await placeFile(tmp, dir, safeSegment(base, 'book'))

    const stat = await fsp.stat(dest)
    const file: DiskFile = {
      rel: path.relative(config.libraryDir, dest).split(path.sep).join('/'),
      abs: dest,
      size: stat.size,
      mtimeMs: Math.trunc(stat.mtimeMs),
    }
    const outcome = await serialize(() =>
      importDiskFile(file, (rel) =>
        fs.existsSync(path.join(config.libraryDir, rel)),
      ),
    )
    if (!outcome.bookId) throw new UploadError(`${fileName} could not be read`)
    return { bookId: outcome.bookId, path: file.rel }
  } finally {
    await fsp.rm(tmp, { force: true })
  }
}

// Copies src into dir as <name>.epub, or "<name> (n).epub" if taken. Hard-links when
// possible (atomic, fails if the name exists); data and library are usually
// different volumes, so fall back to an exclusive copy.
async function placeFile(src: string, dir: string, name: string) {
  for (let n = 0; ; n++) {
    const dest = path.join(dir, n ? `${name} (${n}).epub` : `${name}.epub`)
    try {
      await fsp.link(src, dest)
      return dest
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'EEXIST') continue
    }
    try {
      await fsp.copyFile(src, dest, fs.constants.COPYFILE_EXCL)
      return dest
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'EEXIST') continue
      await fsp.rm(dest, { force: true })
      throw err
    }
  }
}

// One path segment from untrusted text: no separators, reserved or control
// characters, leading dots, or trailing dots/spaces (Windows/SMB shares).
function safeSegment(value: string, fallback: string) {
  const cleaned = value
    // oxlint-disable-next-line no-control-regex
    .replace(/[/\\:*?"<>|\u0000-\u001f\u007f]/g, '_')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^[.\s]+|[.\s]+$/g, '')
    .slice(0, 100)
    .trim()
  return cleaned || fallback
}
import path from 'node:path'
import { strFromU8, unzipSync } from 'fflate'
import { XMLParser } from 'fast-xml-parser'

import type { BookMetadata } from '#/lib/books'

export type EpubCover = { data: Uint8Array; ext: string }

const COVER_TYPES: Record<string, string> = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/gif': 'gif',
  'image/webp': 'webp',
}
const MAX_OPF_BYTES = 5 * 1024 * 1024
const MAX_COVER_BYTES = 20 * 1024 * 1024

const ARRAY_TAGS = new Set([
  'rootfile',
  'item',
  'meta',
  'title',
  'creator',
  'identifier',
  'date',
  'language',
  'publisher',
  'description',
])

const parser = new XMLParser({
  ignoreAttributes: false,
  attributeNamePrefix: '@_',
  removeNSPrefix: true,
  parseTagValue: false,
  // Descriptions often hold (escaped or raw) HTML; keep them as a raw string.
  stopNodes: ['*.description'],
  isArray: (name) => ARRAY_TAGS.has(name),
})

type Node = string | ({ '#text'?: string } & Record<string, unknown>)

const text = (node: Node | undefined) =>
  (typeof node === 'string' ? node : (node?.['#text'] ?? '')).toString().trim()
const attr = (node: Node | undefined, name: string) =>
  typeof node === 'object' && node[`@_${name}`] != null
    ? String(node[`@_${name}`])
    : undefined

// Decompresses only the named entry; throws if it is missing or too large.
function readEntry(zip: Uint8Array, name: string, maxBytes: number) {
  const files = unzipSync(zip, {
    filter: (f) => f.name === name && f.originalSize <= maxBytes,
  })
  const data = files[name]
  if (!data) throw new Error(`Missing or oversized entry: ${name}`)
  return data
}

// Reads metadata and the cover image from an EPUB. Throws on malformed files.
export function readEpub(zip: Uint8Array): {
  metadata: BookMetadata
  cover: EpubCover | null
} {
  const container = parser.parse(
    strFromU8(readEntry(zip, 'META-INF/container.xml', MAX_OPF_BYTES)),
  )
  const opfPath = attr(
    container?.container?.rootfiles?.rootfile?.[0],
    'full-path',
  )
  if (!opfPath) throw new Error('No rootfile in container.xml')

  const pkg = parser.parse(
    strFromU8(readEntry(zip, opfPath, MAX_OPF_BYTES)),
  )?.package
  if (!pkg?.metadata) throw new Error('No package metadata in OPF')
  const md = pkg.metadata as Record<string, Node[] | undefined>
  const metas = md.meta ?? []
  const items = (pkg.manifest?.item ?? []) as Node[]

  const refinement = (node: Node, property: string) => {
    const id = attr(node, 'id')
    const meta = id
      ? metas.find(
          (m) =>
            attr(m, 'refines') === `#${id}` && attr(m, 'property') === property,
        )
      : undefined
    return meta ? text(meta) : undefined
  }
  const first = (values: Node[] | undefined) => {
    const value = values?.map(text).find(Boolean)
    return value || null
  }

  const authors = (md.creator ?? [])
    .filter((c) => {
      const role = attr(c, 'role') ?? refinement(c, 'role')
      return !role || role === 'aut'
    })
    .map(text)
    .filter(Boolean)

  const dates = md.date ?? []
  const date =
    dates.find((d) => {
      const event = attr(d, 'event')
      return !event || event === 'publication'
    }) ?? dates[0]

  const isbn = (md.identifier ?? [])
    .map((id) => {
      const value = text(id)
      if (/^urn:isbn:/i.test(value)) return value.slice(9)
      if (/isbn/i.test(attr(id, 'scheme') ?? '')) return value
      return /^97[89][\d-]{10,14}$/.test(value) ? value : null
    })
    .find(Boolean)

  let series = metas.find((m) => attr(m, 'name') === 'calibre:series')
  let seriesName = series ? attr(series, 'content') : undefined
  let seriesIndex = attr(
    metas.find((m) => attr(m, 'name') === 'calibre:series_index'),
    'content',
  )
  if (!seriesName) {
    series = metas.find((m) => attr(m, 'property') === 'belongs-to-collection')
    if (series) {
      seriesName = text(series)
      seriesIndex = refinement(series, 'group-position')
    }
  }
  const index = seriesIndex ? Number.parseFloat(seriesIndex) : Number.NaN

  const metadata: BookMetadata = {
    title: first(md.title) ?? '',
    authors,
    description: htmlToText(first(md.description) ?? '') || null,
    language: first(md.language),
    publisher: first(md.publisher),
    publishedDate: date
      ? (text(date).match(/^\d{4}(-\d{2}(-\d{2})?)?/)?.[0] ?? null)
      : null,
    isbn: isbn ? isbn.replace(/[^\dX]/gi, '') : null,
    series: seriesName || null,
    seriesIndex: seriesName && Number.isFinite(index) ? index : null,
  }

  return { metadata, cover: readCover(zip, opfPath, items, metas) }
}

function readCover(
  zip: Uint8Array,
  opfPath: string,
  items: Node[],
  metas: Node[],
): EpubCover | null {
  const coverRef = attr(
    metas.find((m) => attr(m, 'name') === 'cover'),
    'content',
  )
  const isImage = (i: Node) => (attr(i, 'media-type') ?? '') in COVER_TYPES
  const item =
    // EPUB 3
    items.find((i) =>
      (attr(i, 'properties') ?? '').split(/\s+/).includes('cover-image'),
    ) ??
    // EPUB 2: <meta name="cover" content="<item id>">, sometimes an href
    (coverRef
      ? items.find(
          (i) => attr(i, 'id') === coverRef || attr(i, 'href') === coverRef,
        )
      : undefined) ??
    // Fallback: an image whose id or file name says "cover"
    items.find(
      (i) => isImage(i) && /cover/i.test(`${attr(i, 'id')} ${attr(i, 'href')}`),
    )
  const href = attr(item, 'href')
  const ext = COVER_TYPES[attr(item, 'media-type') ?? '']
  if (!item || !href || !ext) return null

  let name: string
  try {
    name = path.posix.join(
      path.posix.dirname(opfPath),
      decodeURIComponent(href),
    )
  } catch {
    return null
  }
  try {
    return { data: readEntry(zip, name, MAX_COVER_BYTES), ext }
  } catch {
    return null
  }
}

const ENTITIES: Record<string, string> = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  apos: "'",
  nbsp: ' ',
  ndash: '–',
  mdash: '—',
  hellip: '…',
  lsquo: '‘',
  rsquo: '’',
  ldquo: '“',
  rdquo: '”',
}

function decodeEntities(s: string) {
  return s.replace(/&(#x[\da-f]+|#\d+|[a-z]+);/gi, (match, code: string) => {
    if (code[0] !== '#') return ENTITIES[code.toLowerCase()] ?? match
    const n =
      code[1] === 'x' || code[1] === 'X'
        ? Number.parseInt(code.slice(2), 16)
        : Number.parseInt(code.slice(1), 10)
    return n > 0 && n <= 0x10ffff ? String.fromCodePoint(n) : match
  })
}

// OPF descriptions (and Google Books ones) are often (escaped) HTML. Reduce them
// to plain text with paragraph breaks; the UI renders the result as text, never as HTML.
export function htmlToText(html: string) {
  return decodeEntities(
    decodeEntities(html)
      .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|li|h[1-6])>/gi, '\n\n')
      .replace(/<[^>]*>/g, ''),
  )
    .replace(/[ \t\r\f\v]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
}
import { createServerFn } from '@tanstack/react-start'
import { getRequestHeaders } from '@tanstack/react-start/server'

import { db } from '#/db'
import { user } from '#/db/schema'
import { auth, syntheticEmail } from '#/lib/auth'
import { checkPassword, checkUsername } from '#/lib/credentials'

function hasUsers() {
  return db.select({ id: user.id }).from(user).limit(1).get() !== undefined
}

// Read by the root route on every navigation; children get `user` from route context.
export const getAuthState = createServerFn({ method: 'GET' }).handler(
  async () => {
    const session = await auth.api.getSession({ headers: getRequestHeaders() })
    if (!session) return { hasUsers: hasUsers(), user: null }
    const { id, username, role } = session.user
    return { hasUsers: true, user: { id, username: username ?? '', role } }
  },
)

type Credentials = { username: string; password: string }

// Creates the first user as admin and signs them in. Refuses once any user exists.
export const setupAdmin = createServerFn({ method: 'POST' })
  .validator((data: Credentials) => {
    checkUsername(data.username)
    checkPassword(data.password)
    return data
  })
  .handler(async ({ data }) => {
    if (hasUsers()) throw new Error('Setup is already complete')
    await auth.api.createUser({
      body: {
        email: syntheticEmail(data.username),
        password: data.password,
        name: data.username,
        role: 'admin',
        data: { username: data.username },
      },
    })
    await auth.api.signInUsername({
      body: { username: data.username, password: data.password },
      headers: getRequestHeaders(),
    })
  })
import { createServerFn, createServerOnlyFn } from '@tanstack/react-start'
import { getRequestHeaders } from '@tanstack/react-start/server'
import { isAPIError } from 'better-auth/api'
import { count, eq } from 'drizzle-orm'

import { db } from '#/db'
import { user } from '#/db/schema'
import { auth, syntheticEmail } from '#/lib/auth'
import { checkPassword, checkUsername } from '#/lib/credentials'

export type Role = 'admin' | 'user'

// Every admin server function handler starts with this. Pass `headers` on to
// auth.api calls so Better Auth's admin plugin checks the same session.
export const requireAdmin = createServerOnlyFn(async () => {
  const headers = getRequestHeaders()
  const session = await auth.api.getSession({ headers })
  if (session?.user.role !== 'admin') throw new Error('Forbidden')
  return { headers, session }
})

function checkRole(role: string): asserts role is Role {
  if (role !== 'admin' && role !== 'user') throw new Error('Invalid role')
}

function isLastAdmin(userId: string) {
  const target = db
    .select({ role: user.role })
    .from(user)
    .where(eq(user.id, userId))
    .get()
  if (target?.role !== 'admin') return false
  const admins = db
    .select({ n: count() })
    .from(user)
    .where(eq(user.role, 'admin'))
    .get()
  return (admins?.n ?? 0) <= 1
}

// Surface Better Auth's APIError messages as plain errors for the UI.
function rethrow(err: unknown): never {
  // The email is derived from the username, so a taken email means a taken username.
  if (
    isAPIError(err) &&
    err.body?.code === 'USER_ALREADY_EXISTS_USE_ANOTHER_EMAIL'
  ) {
    throw new Error('Username is already taken')
  }
  throw new Error(err instanceof Error ? err.message : 'Request failed')
}

export const listUsers = createServerFn({ method: 'GET' }).handler(async () => {
  const { headers } = await requireAdmin()
  const { users } = await auth.api.listUsers({
    query: { sortBy: 'createdAt' },
    headers,
  })
  // The username plugin's fields are returned at runtime but missing from the type.
  return (users as Array<(typeof users)[number] & { username: string }>).map(
    (u) => ({
      id: u.id,
      username: u.username,
      role: u.role === 'admin' ? 'admin' : 'user',
      createdAt: new Date(u.createdAt).toISOString(),
    }),
  )
})

export const createUser = createServerFn({ method: 'POST' })
  .validator((data: { username: string; password: string; role: string }) => {
    checkUsername(data.username)
    checkPassword(data.password)
    checkRole(data.role)
    return { ...data, role: data.role }
  })
  .handler(async ({ data }) => {
    const { headers } = await requireAdmin()
    await auth.api
      .createUser({
        body: {
          email: syntheticEmail(data.username),
          password: data.password,
          name: data.username,
          role: data.role,
          data: { username: data.username },
        },
        headers,
      })
      .catch(rethrow)
  })

export const setRole = createServerFn({ method: 'POST' })
  .validator((data: { userId: string; role: string }) => {
    checkRole(data.role)
    return { ...data, role: data.role }
  })
  .handler(async ({ data }) => {
    const { headers, session } = await requireAdmin()
    if (data.role === 'user' && isLastAdmin(data.userId)) {
      throw new Error('The last admin cannot be demoted')
    }
    if (data.userId === session.user.id) {
      throw new Error('You cannot change your own role')
    }
    await auth.api
      .setRole({ body: { userId: data.userId, role: data.role }, headers })
      .catch(rethrow)
  })

export const setUserPassword = createServerFn({ method: 'POST' })
  .validator((data: { userId: string; password: string }) => {
    checkPassword(data.password)
    return data
  })
  .handler(async ({ data }) => {
    const { headers } = await requireAdmin()
    await auth.api
      .setUserPassword({
        body: { userId: data.userId, newPassword: data.password },
        headers,
      })
      .catch(rethrow)
  })

export const removeUser = createServerFn({ method: 'POST' })
  .validator((data: { userId: string }) => data)
  .handler(async ({ data }) => {
    const { headers, session } = await requireAdmin()
    if (isLastAdmin(data.userId)) {
      throw new Error('The last admin cannot be deleted')
    }
    if (data.userId === session.user.id) {
      throw new Error('You cannot delete your own account')
    }
    await auth.api
      .removeUser({ body: { userId: data.userId }, headers })
      .catch(rethrow)
  })
#!/usr/bin/env bash
# Prepares a fresh Amp orb: Node dependencies, the Entire CLI, and the
# entire-agent-amp external agent. Idempotent; a warm run skips installed tools.
set -euo pipefail
cd "$(dirname "$0")/.."

GO_VERSION=1.26.10
ENTIRE_VERSION=0.12.2
# entireio/external-agents has no releases; pin the commit to build from.
ENTIRE_AGENT_AMP_REV=23c64f2861ddbfd2670cffafeb45f86bad6ebc2b

bin_dir="$HOME/.local/bin" # already on PATH in orb login shells
go_root="$HOME/.local/go"
case "$(uname -m)" in
  x86_64 | amd64) arch=amd64 ;;
  aarch64 | arm64) arch=arm64 ;;
  *) echo "unsupported arch: $(uname -m)" >&2; exit 1 ;;
esac
mkdir -p "$bin_dir"

step() {
  local name=$1 start=$SECONDS
  shift
  echo "==> $name"
  "$@"
  echo "    $name took $((SECONDS - start))s"
}

install_entire() {
  if "$bin_dir/entire" version 2>/dev/null | grep -Fq "Entire CLI $ENTIRE_VERSION"; then
    echo "    entire $ENTIRE_VERSION already installed"
    return
  fi
  local tmp
  tmp=$(mktemp -d)
  curl -fsSL "https://github.com/entireio/cli/releases/download/v$ENTIRE_VERSION/entire_linux_$arch.tar.gz" |
    tar xz -C "$tmp" entire git-remote-entire
  install -m 755 "$tmp/entire" "$tmp/git-remote-entire" "$bin_dir/"
  rm -rf "$tmp"
}

install_go() {
  if "$go_root/bin/go" version 2>/dev/null | grep -Fq "go$GO_VERSION "; then
    echo "    go $GO_VERSION already installed"
    return
  fi
  rm -rf "$go_root"
  curl -fsSL "https://go.dev/dl/go$GO_VERSION.linux-$arch.tar.gz" | tar xz -C "$(dirname "$go_root")"
}

install_entire_agent_amp() {
  # The pseudo-version embedded in the binary ends with the first 12 chars of the commit.
  if "$go_root/bin/go" version -m "$bin_dir/entire-agent-amp" 2>/dev/null | grep -Fq "${ENTIRE_AGENT_AMP_REV:0:12}"; then
    echo "    entire-agent-amp ${ENTIRE_AGENT_AMP_REV:0:12} already installed"
    return
  fi
  GOBIN="$bin_dir" "$go_root/bin/go" install \
    "github.com/entireio/external-agents/agents/entire-agent-amp/cmd/entire-agent-amp@$ENTIRE_AGENT_AMP_REV"
}

step "pnpm install" pnpm install --frozen-lockfile
step "entire CLI" install_entire
step "go toolchain" install_go
step "entire-agent-amp" install_entire_agent_amp
